import{c as t,Q as i,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"Sonnet-5 Fresh-Context Adversarial Review of Fusion Architecture Design","description":"","frontmatter":{"title":"Sonnet-5 Fresh-Context Adversarial Review of Fusion Architecture Design","date":"2026-07-09T00:00:00.000Z","status":"done","ground-truth-read":[".claude/refs/delegation-protocol.md (§1, §4, §6)",".claude/rules/context-management.md (Static First, mid-session prohibition)",".claude/refs/model-profiles.md (§0, §1, §2.3, §2.4, §3, §6)",".claude/skills/multi-mode-skill/SKILL.md (§0, §1, §2, §4)","AGENTS.md (§2, §4, §6b)","research/archive/the-loop-harness-v3/HARNESS-CORE-v3.md (v3 鐵律, §6)",".claude/agents/multi-mode-agent.md (frontmatter, 不變式, Mode 紀律表)"],"mechanical-verification":{"protocol-draft-bytes":1077,"protocol-draft-model-name-hits":0,"phase2-config-docs-mentions":32,"token-sim-math-spotcheck":"pass"},"parent-artifacts":["research/reports/2026-07-09-fusion-architecture-design-plan.md","research/reports/2026-07-09-fusion-glm-architecture-validation.md","research/reports/2026-07-09-fusion-glm-factory-phase2-config.md","research/reports/2026-07-09-fusion-kimi-token-simulation.md","research/reports/2026-07-09-fusion-kimi-agents-md-protocol-draft.md"],"reviewer":"Sonnet-5 (ceiling tier, fresh context, adversarial mode)","type":"cross-review"},"headers":[],"relativePath":"research/reports/2026-07-09-cross-review-sonnet-adversarial.md","filePath":"research/reports/2026-07-09-cross-review-sonnet-adversarial.md","lastUpdated":1785909234000}'),s={name:"research/reports/2026-07-09-cross-review-sonnet-adversarial.md"};function n(r,e,d,c,l,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="sonnet-5-fresh-context-adversarial-review-of-fusion-architecture-design" tabindex="-1">Sonnet-5 Fresh-Context Adversarial Review of Fusion Architecture Design <a class="header-anchor" href="#sonnet-5-fresh-context-adversarial-review-of-fusion-architecture-design" aria-label="Permalink to &quot;Sonnet-5 Fresh-Context Adversarial Review of Fusion Architecture Design&quot;">​</a></h1><h2 id="reviewer-context" tabindex="-1">Reviewer Context <a class="header-anchor" href="#reviewer-context" aria-label="Permalink to &quot;Reviewer Context&quot;">​</a></h2><ul><li>Model: Sonnet-5 (ceiling tier, fresh context)</li><li>Mode: Adversarial — assume wrong until proven correct</li><li>Scope: Full Fusion architecture design + 4 sub-reports + 7 ground-truth workspace files</li><li>Method: Read every artifact fresh, verify every load-bearing claim against workspace SSoT, spot-check arithmetic mechanically.</li></ul><hr><h2 id="part-a-architectural-soundness" tabindex="-1">Part A: Architectural Soundness <a class="header-anchor" href="#part-a-architectural-soundness" aria-label="Permalink to &quot;Part A: Architectural Soundness&quot;">​</a></h2><h3 id="a1-three-layer-architecture-is-well-defined-but-has-a-naming-numbering-inconsistency" tabindex="-1">A1. Three-layer architecture is well-defined but has a naming/numbering inconsistency <a class="header-anchor" href="#a1-three-layer-architecture-is-well-defined-but-has-a-naming-numbering-inconsistency" aria-label="Permalink to &quot;A1. Three-layer architecture is well-defined but has a naming/numbering inconsistency&quot;">​</a></h3><p>The design plan §2.2 presents <strong>four</strong> boxes labelled L0–L3 (Fusion Router, Main Agent, Sidekick Agent, Compaction Gate), yet the section title and §2 references call it a &quot;三層架構&quot; (three-layer). The Compaction Gate is described as L3 but is not a persistent agent layer — it is a <em>transition trigger</em> embedded in the other layers. This is a presentation defect, not a soundness defect, but in a ceiling-tier design doc the L-numbering ambiguity will cause downstream implementers to misplace the gate (is it a layer or a hook?). <strong>Recommend: rename to &quot;3 layers + 1 cross-cutting gate&quot; and drop the L3 label, or renumber consistently.</strong></p><h3 id="a2-boundaries-between-layers-are-mostly-clear-with-one-leakage" tabindex="-1">A2. Boundaries between layers are mostly clear, with one leakage <a class="header-anchor" href="#a2-boundaries-between-layers-are-mostly-clear-with-one-leakage" aria-label="Permalink to &quot;A2. Boundaries between layers are mostly clear, with one leakage&quot;">​</a></h3><ul><li>L0 (Router) → L1 (Main): clear — Router classifies, Main executes/plans. ✅</li><li>L1 (Main) → L2 (Sidekick): clear — Main delegates, Sidekick reports conclusions only. ✅ Aligned with delegation-protocol.md §4.</li><li>L2 (Sidekick) → L3 (Compaction Gate): <strong>leakage</strong>. The Compaction Gate is drawn as a sibling of Sidekick but its trigger condition (&quot;compaction 觸發 → 評估是否升降級&quot;) is a <em>Main session</em> event, not a Sidekick event. In the Claude Code path, sidekick is a one-shot sub-agent spawn (per GLM validation §優化項 4) and has <strong>no compaction of its own that matters to routing</strong> — the sidekick&#39;s context dies when the spawn ends. So the &quot;compaction-time switching&quot; lever only applies to the <strong>Main agent&#39;s</strong> compaction, which in the Claude Code path is governed by context-management.md&#39;s mid-session prohibition (see Part B). The architecture diagram implies the gate watches both contexts; in reality on Claude Code it watches only Main, and on Factory it can patch the session. The diagram should annotate which context the gate binds to per harness.</li></ul><h3 id="a3-missing-feedback-loop-sidekick-failure-→-main-upgrade-path-is-described-but-sidekick-success-→-main-downgrade-is-not-a-real-feedback-loop" tabindex="-1">A3. Missing feedback loop: Sidekick failure → Main upgrade path is described, but Sidekick success → Main downgrade is not a real feedback loop <a class="header-anchor" href="#a3-missing-feedback-loop-sidekick-failure-→-main-upgrade-path-is-described-but-sidekick-success-→-main-downgrade-is-not-a-real-feedback-loop" aria-label="Permalink to &quot;A3. Missing feedback loop: Sidekick failure → Main upgrade path is described, but Sidekick success → Main downgrade is not a real feedback loop&quot;">​</a></h3><p>§2.5 Protocol says &quot;機械模式確認 → 降級&quot; and &quot;連續失敗 → 升級&quot;. The upgrade side is concrete (delegation-protocol.md §5 + §6 verification chain). The <strong>downgrade side is hand-waved</strong>: &quot;高檔位解出模式寫成規則,降 cost 批次套用&quot; requires a human-or-Main step to <em>extract the pattern into a rule</em> before downgrading. There is no automated mechanism for &quot;sidekick confirmed mechanical → downgrade Main&#39;s next-task tier&quot;. This is a decision the Router (L0) must make, but the Router in the Claude Code path is the static-position-count classifier from multi-mode-skill §1, which does <strong>not</strong> receive sidekick success as an input. So the &quot;dynamic routing&quot; claim is true for Factory (Session API PATCH can react) but <strong>not for Claude Code Phase 1</strong>, where routing remains static-position-count with post-failure escalation only. The design plan §1.2 honestly lists this as a gap (&quot;workspace 無執行中動態升降級&quot;), but §2.5 Protocol draft then presents the downgrade as a general rule without scoping it to Factory-only. <strong>Recommend: annotate the Protocol&#39;s downgrade row as &quot;Factory path only; Claude Code = post-task escalation&quot;.</strong></p><h3 id="a4-compaction-time-switching-zero-cache-penalty-claim-—-partially-holds-with-a-critical-caveat" tabindex="-1">A4. &quot;Compaction-time switching = zero cache penalty&quot; claim — partially holds, with a critical caveat <a class="header-anchor" href="#a4-compaction-time-switching-zero-cache-penalty-claim-—-partially-holds-with-a-critical-caveat" aria-label="Permalink to &quot;A4. &quot;Compaction-time switching = zero cache penalty&quot; claim — partially holds, with a critical caveat&quot;">​</a></h3><p>The core Devin Fusion insight (compaction already invalidates cache, so switching model then is &quot;free&quot;) is <strong>sound in principle</strong>. But the design over-extends it in two ways:</p><ol><li><p><strong>Compaction does not <em>fully</em> invalidate cache.</strong> Anthropic prompt caching has a 5-minute TTL and a minimum block size (Haiku/Opus = 4,096 tokens, Sonnet 4.6/frontier = 2,048 per model-profiles.md §2.4). A compaction rewrites the <em>middle</em> of context but the <strong>stable prefix</strong> (CLAUDE.md/AGENTS.md/system prompt) is designed to <em>survive</em> compaction — that is the entire point of &quot;Static First&quot; in context-management.md. If the prefix survives compaction and remains cacheable, then switching the <em>main</em> model at compaction time <strong>does</strong> invalidate the prefix cache (different model = different cache namespace). So &quot;zero cache penalty&quot; is only true for the <em>compactionModel</em> swap (the compaction output model), <strong>not</strong> for swapping the main session model at compaction time. The design conflates the two: §2.2 L3 says &quot;compaction 觸發 → 評估是否升級/降級模型&quot; (main model swap), but the cache-zero claim only rigorously applies to the compactionModel field. <strong>This is a load-bearing conflation.</strong> For the Factory path, swapping the main model via Session API PATCH at compaction time <em>does</em> cost the prefix cache of the new model (first-read full price) — it is &quot;free&quot; only relative to swapping at a non-compaction moment, not absolutely free.</p></li><li><p><strong>Claude Code path cannot do main-model swap at all</strong> (see Part B), so on Claude Code the only compaction-time lever is the compactionModel, which Claude Code does not expose as configurable (it uses the current model per context-management.md). The &quot;zero cache penalty&quot; benefit is therefore <strong>Factory-only</strong>, but §2.2 presents it as a general architectural property.</p></li></ol><p><strong>Verdict on A4:</strong> The claim is <em>directionally correct but over-stated</em>. Precise statement: &quot;swapping compactionModel at compaction time = zero extra cache penalty; swapping the main session model at compaction time = one-time prefix re-cache cost on the new model, which is still cheaper than swapping mid-turn.&quot; The design should state this precisely.</p><hr><h2 id="part-b-claude-code-vs-factory-droid-path-divergence" tabindex="-1">Part B: Claude Code vs Factory Droid Path Divergence <a class="header-anchor" href="#part-b-claude-code-vs-factory-droid-path-divergence" aria-label="Permalink to &quot;Part B: Claude Code vs Factory Droid Path Divergence&quot;">​</a></h2><h3 id="b1-claude-code-cannot-do-mid-session-model-switching-—-accurate-verified" tabindex="-1">B1. &quot;Claude Code cannot do mid-session model switching&quot; — ACCURATE, verified <a class="header-anchor" href="#b1-claude-code-cannot-do-mid-session-model-switching-—-accurate-verified" aria-label="Permalink to &quot;B1. &quot;Claude Code cannot do mid-session model switching&quot; — ACCURATE, verified&quot;">​</a></h3><p>context-management.md (Prompt Caching / Static First) states verbatim: &quot;<strong>Mid-session 禁止</strong>切換模型/增刪 tool/改 CLAUDE.md（破快取）；能力升級需求 → sub-agent 檔位 override（載體 <code>multi-mode-agent</code>）或新 session,不切主對話模型。&quot; multi-mode-skill §0 不變式 repeats: &quot;model 在 spawn 時綁定,主對話 mid-session 不切 model&quot;. multi-mode-agent.md frontmatter <code>isolation: worktree</code> + 不變式 &quot;你的 model 由 parent 在 spawn 時綁定,不可自切&quot; confirms sub-agents also cannot mid-run switch.</p><p><strong>The design&#39;s claim is correct and well-grounded.</strong> The Claude Code path correctly routes around this via sub-agent spawn (new context) rather than main-session switching. ✅</p><h3 id="b2-factory-session-api-patch-capability-—-correctly-described-with-one-undocumented-field-flagged" tabindex="-1">B2. Factory Session API PATCH capability — correctly described, with one undocumented field flagged <a class="header-anchor" href="#b2-factory-session-api-patch-capability-—-correctly-described-with-one-undocumented-field-flagged" aria-label="Permalink to &quot;B2. Factory Session API PATCH capability — correctly described, with one undocumented field flagged&quot;">​</a></h3><p>The phase2-config sub-report (GLM-B) is admirably honest: it explicitly flags that <code>providerLock</code> is <strong>not</strong> a documented CLI switch (步驟 3 &quot;重要修正&quot;), that <code>providerLockTimestamp</code> exists in the API but its <em>semantics are undocumented</em>, and that the exact <code>model</code> ID strings for Factory Router and Haiku 4.5 are not in the docs and must be read from the picker. This is exactly the &quot;trust but verify&quot; discipline the workspace demands. ✅</p><p>However, the main design plan §1.3 presents <code>providerLock</code> as &quot;✅ Session 層級&quot; (a supported feature) without the caveat that GLM-B later discovered. <strong>There is an internal contradiction between the main plan (claims providerLock is a supported session-level feature) and the sub-report (finds it is not a settable CLI switch, only an undocumented API timestamp field).</strong> The main plan should be updated to reflect GLM-B&#39;s finding, or the sub-report&#39;s &quot;⚠️ 需確認&quot; should propagate up.</p><h3 id="b3-hidden-assumptions-about-factory-api-behavior" tabindex="-1">B3. Hidden assumptions about Factory API behavior <a class="header-anchor" href="#b3-hidden-assumptions-about-factory-api-behavior" aria-label="Permalink to &quot;B3. Hidden assumptions about Factory API behavior&quot;">​</a></h3><p>Three hidden assumptions that might not hold:</p><ol><li><p><strong><code>compactionModel</code> swap preserves session continuity.</strong> The design assumes PATCHing <code>compactionModel</code> mid-session is safe and the session resumes cleanly. The docs (D6) confirm the field exists and PATCH returns 200 with the setting, but there is <strong>no documented guarantee that changing compactionModel mid-session doesn&#39;t trigger an immediate re-compaction or reset compaction state</strong>. This needs empirical verification before relying on it.</p></li><li><p><strong><code>compactionThresholdCheckEnabled: true</code> exposes a compaction-trigger signal to the caller.</strong> Phase 3 (§2.4) says &quot;偵測 compaction 觸發 (compactionThresholdCheckEnabled: true)&quot; — but this flag <em>enables threshold checking</em>, it does not <em>emit an event the caller can hook</em>. The design assumes a polling/event model for &quot;detect compaction triggered → PATCH model&quot; that is not documented. The actual mechanism (webhook? polling GET session? CLI hook?) is unspecified. <strong>This is the single biggest unstated assumption in the Factory Phase 3 design.</strong></p></li><li><p><strong>Factory Router is treated as a settable <code>model</code> value.</strong> GLM-B correctly flags the ID string is undocumented, but the deeper assumption is that Router can be <em>combined</em> with a separately-configured <code>compactionModel</code>. If Router is itself doing per-task model routing, layering a fixed compactionModel on top may interact (does Router override compactionModel per-task? unknown). The design does not address this interaction.</p></li></ol><hr><h2 id="part-c-token-savings-claims" tabindex="-1">Part C: Token Savings Claims <a class="header-anchor" href="#part-c-token-savings-claims" aria-label="Permalink to &quot;Part C: Token Savings Claims&quot;">​</a></h2><h3 id="c1-35-2-cost-weighted-savings-—-math-verified-but-the-weighting-is-the-weak-point" tabindex="-1">C1. -35.2% cost-weighted savings — math verified, but the weighting is the weak point <a class="header-anchor" href="#c1-35-2-cost-weighted-savings-—-math-verified-but-the-weighting-is-the-weak-point" aria-label="Permalink to &quot;C1. -35.2% cost-weighted savings — math verified, but the weighting is the weak point&quot;">​</a></h3><p>I mechanically spot-checked the arithmetic (Python recompute):</p><table tabindex="0"><thead><tr><th>Task</th><th>Reported existing</th><th>Recomputed existing</th><th>Reported fusion</th><th>Recomputed fusion</th><th>Reported %</th><th>Recomputed %</th></tr></thead><tbody><tr><td>3 (deep research)</td><td>$0.4613</td><td>$0.4612</td><td>$0.2925</td><td>$0.2925</td><td>37%</td><td>36.6%</td></tr><tr><td>5 (large migration)</td><td>$1.536</td><td>$1.536</td><td>$0.729</td><td>$0.729</td><td>53%</td><td>52.5%</td></tr><tr><td><strong>Aggregate</strong></td><td>$2.477</td><td>$2.4772</td><td>$1.605</td><td>$1.6046</td><td>-35.2%</td><td>-35.2%</td></tr></tbody></table><p><strong>Arithmetic is correct</strong> (rounding-only differences). ✅</p><p><strong>But the -35.2% headline is fragile because it is dominated by a single task type:</strong></p><table tabindex="0"><thead><tr><th>Task</th><th>Share of existing total cost</th></tr></thead><tbody><tr><td>5 (large migration)</td><td>56.0%</td></tr><tr><td>3 (deep research)</td><td>21.6%</td></tr><tr><td>4 (security review)</td><td>17.3%</td></tr><tr><td>2 (cross-module refactor)</td><td>4.6%</td></tr><tr><td>1 (single-file)</td><td>0.5%</td></tr></tbody></table><p>Task 5 alone contributes -29.7pp of the -35.2% (i.e., <strong>84% of the headline savings come from one task type</strong> that the simulation itself flags as &quot;量級不同,僅供架構對比&quot; and based on a Twitter-sourced, unconfirmed $1,146 figure). If Task 5&#39;s frequency or cost share is even half of the assumed 56%, the aggregate drops to ~-20%. The frequency-weighted view (+2.8%) tells the opposite story. <strong>The truth is task-structure-dependent, and the design plan headline leans on the cost-weighted number while burying the frequency-weighted number.</strong> A ceiling-tier doc should lead with <em>both</em> and state the dependency explicitly.</p><h3 id="c2-sidekick-overhead-accounting-—-partially-accounted-two-gaps" tabindex="-1">C2. Sidekick overhead accounting — partially accounted, two gaps <a class="header-anchor" href="#c2-sidekick-overhead-accounting-—-partially-accounted-two-gaps" aria-label="Permalink to &quot;C2. Sidekick overhead accounting — partially accounted, two gaps&quot;">​</a></h3><p>The simulation <em>does</em> account for spawn cost (sidekick input/output tokens are line-itemed) and context transfer (sub-agent 交辦 prompt ~1,500 tokens is in §1.3). Good. Two gaps:</p><ol><li><p><strong>Verification overhead is not costed.</strong> delegation-protocol.md §6 requires &quot;sidekick 產出由 main 機械重驗&quot; — the Main agent re-reads/re-greps the sidekick&#39;s output. This verification cost (Main agent input tokens to re-read the diff/files) is <strong>not in any task&#39;s Fusion column</strong>. For Task 5 (16 PRs), Main reviewing each PR&#39;s 50-line diff = 16 × (read diff + grep verify) is non-trivial and would erode the 53%. The simulation mentions &quot;ceiling 審查每個 PR（已含）&quot; in the 品質影響 note but the Main input token line (40,000) does not visibly include 16 × diff-read. <strong>Under-costed by likely 10-20k Main input tokens for Task 5.</strong></p></li><li><p><strong>Session overhead (O9) is explicitly excluded</strong> (§5 limitation 5 acknowledges this). model-profiles.md §5 O9: cost 檔位 fixed overhead 76.2k tokens &gt; quality 73.9k. For Task 1 (single-file, $0.0117), the real cost is dominated by overhead, so the &quot;0% difference&quot; is correct in <em>delta</em> but misleading in <em>absolute</em> terms — both architectures pay ~$0.05-0.10 of fixed overhead the simulation omits. Not a savings error, but the per-task absolute numbers are lower bounds.</p></li></ol><h3 id="c3-36-cost-increase-for-cross-module-refactor-task-2-—-acceptable-as-a-design-choice-but-the-framing-is-a-design-flaw" tabindex="-1">C3. +36% cost increase for cross-module refactor (Task 2) — acceptable as a design choice, but the framing is a design flaw <a class="header-anchor" href="#c3-36-cost-increase-for-cross-module-refactor-task-2-—-acceptable-as-a-design-choice-but-the-framing-is-a-design-flaw" aria-label="Permalink to &quot;C3. +36% cost increase for cross-module refactor (Task 2) — acceptable as a design choice, but the framing is a design flaw&quot;">​</a></h3><p>Task 2 goes from $0.0984 (quality親做) to $0.1341 (ceiling main + cost sidekick) = +36%. The simulation justifies this as &quot;品質換成本&quot; (ceiling planning + adversarial review improves quality). <strong>This is a legitimate design choice, but it is <em>not token savings</em> — it is a quality upgrade priced as a cost increase.</strong> The problem is the <em>architecture name</em>: &quot;Token 節省策略&quot; (Token Saving Strategy) implies savings across the board. A design that increases cost on 25% of tasks (by frequency) / 4.6% (by cost) while saving on 30% is really a <strong>quality-cost reallocation</strong>, not a savings strategy. The frequency-weighted +2.8% makes this visible. <strong>Recommend: reframe §3 from &quot;Token 節省策略&quot; to &quot;Token 重分配 + 節省策略&quot; and explicitly mark Tasks 2 &amp; 4 as quality-investment zones where cost increase is intentional and accepted.</strong> Currently the design quietly absorbs the increase under a savings headline.</p><hr><h2 id="part-d-workspace-alignment" tabindex="-1">Part D: Workspace Alignment <a class="header-anchor" href="#part-d-workspace-alignment" aria-label="Permalink to &quot;Part D: Workspace Alignment&quot;">​</a></h2><h3 id="d1-§5-2-claim-mid-session-禁止切換模型-—-claude-code-路徑用-sub-agent-spawn-不切主對話-—-consistent-✅" tabindex="-1">D1. §5.2 claim: &quot;Mid-session 禁止切換模型 — Claude Code 路徑用 sub-agent spawn 不切主對話&quot; — CONSISTENT ✅ <a class="header-anchor" href="#d1-§5-2-claim-mid-session-禁止切換模型-—-claude-code-路徑用-sub-agent-spawn-不切主對話-—-consistent-✅" aria-label="Permalink to &quot;D1. §5.2 claim: &quot;Mid-session 禁止切換模型 — Claude Code 路徑用 sub-agent spawn 不切主對話&quot; — CONSISTENT ✅&quot;">​</a></h3><p>Verified against context-management.md (&quot;能力升級需求 → sub-agent 檔位 override&quot;) and multi-mode-skill §0 (&quot;要換檔位 → 用 sub-agent <code>model</code> override 或新 session&quot;). The Claude Code path is genuinely compliant. The claim is accurate.</p><h3 id="d2-§5-2-claim-factory-路徑用-compaction-時切換-api-原生支援-—-consistent-but-with-the-cache-caveat-from-a4" tabindex="-1">D2. §5.2 claim: &quot;Factory 路徑用 compaction 時切換（API 原生支援）&quot; — CONSISTENT but with the cache caveat from A4 <a class="header-anchor" href="#d2-§5-2-claim-factory-路徑用-compaction-時切換-api-原生支援-—-consistent-but-with-the-cache-caveat-from-a4" aria-label="Permalink to &quot;D2. §5.2 claim: &quot;Factory 路徑用 compaction 時切換（API 原生支援）&quot; — CONSISTENT but with the cache caveat from A4&quot;">​</a></h3><p>Factory Session API PATCH of <code>compactionModel</code> is documented (D6). ✅ But the §5.2 table frames this as simply &quot;API 原生支援&quot; without noting that swapping the <em>main</em> model (not just compactionModel) at compaction time still costs prefix cache (see A4). The claim is <em>literally</em> consistent (the API does support it) but <em>rhetorically</em> overclaims the cache-zero benefit.</p><h3 id="d3-§5-2-claim-l1-零模型名-—-agents-md-fusion-protocol-不含模型名-—-verified-✅-with-a-structural-caveat" tabindex="-1">D3. §5.2 claim: &quot;L1 零模型名 — AGENTS.md Fusion Protocol 不含模型名&quot; — VERIFIED ✅ (with a structural caveat) <a class="header-anchor" href="#d3-§5-2-claim-l1-零模型名-—-agents-md-fusion-protocol-不含模型名-—-verified-✅-with-a-structural-caveat" aria-label="Permalink to &quot;D3. §5.2 claim: &quot;L1 零模型名 — AGENTS.md Fusion Protocol 不含模型名&quot; — VERIFIED ✅ (with a structural caveat)&quot;">​</a></h3><p>Mechanical verification: the protocol draft (kimi-agents-md-protocol-draft.md) is <strong>1077 bytes</strong> (≤1200 ✅) and contains <strong>0</strong> matches for <code>opus|sonnet|haiku|fable|glm|kimi|gpt|claude|anthropic|openai</code> (✅). The draft uses tier words (cost/ceiling) and &quot;cost 檔&quot; only. <strong>Compliant with HARNESS-CORE-v3 v3 鐵律</strong> (&quot;L1 不出現模型名&quot;).</p><p><strong>Structural caveat:</strong> The draft is labelled &quot;§7. Fusion Protocol&quot; but the <em>live</em> AGENTS.md currently ends at §6b (verified: no §7, no &quot;Fusion Protocol&quot; string in the live file). So the draft is a <strong>proposal not yet merged</strong>. The design plan §2.5 and §5.2 present it as if it were a workspace rule (&quot;在 AGENTS.md 新增&quot;), which is correct intent but the §5.2 table row &quot;本設計如何遵守&quot; implies the Protocol is already enforcing — it is not yet enforced. <strong>Recommend: §5.2 should say &quot;（草案,待 merge）&quot; for the L1 row.</strong></p><h3 id="d4-§5-2-claim-指揮官不下場-—-main-agent-預設委派-例外親做-—-consistent-✅" tabindex="-1">D4. §5.2 claim: &quot;指揮官不下場 — Main Agent 預設委派,例外親做&quot; — CONSISTENT ✅ <a class="header-anchor" href="#d4-§5-2-claim-指揮官不下場-—-main-agent-預設委派-例外親做-—-consistent-✅" aria-label="Permalink to &quot;D4. §5.2 claim: &quot;指揮官不下場 — Main Agent 預設委派,例外親做&quot; — CONSISTENT ✅&quot;">​</a></h3><p>Matches delegation-protocol.md §1 verbatim (&quot;預設委派、例外親做&quot;). The Fusion Main Agent role is a direct mapping of the existing 指揮官 concept. ✅</p><h3 id="d5-§5-2-claim-驗證不自驗-—-sidekick-產出由-main-agent-機械重驗-—-consistent-✅" tabindex="-1">D5. §5.2 claim: &quot;驗證不自驗 — Sidekick 產出由 Main Agent 機械重驗&quot; — CONSISTENT ✅ <a class="header-anchor" href="#d5-§5-2-claim-驗證不自驗-—-sidekick-產出由-main-agent-機械重驗-—-consistent-✅" aria-label="Permalink to &quot;D5. §5.2 claim: &quot;驗證不自驗 — Sidekick 產出由 Main Agent 機械重驗&quot; — CONSISTENT ✅&quot;">​</a></h3><p>Matches delegation-protocol.md §6 (&quot;產出者不得驗收自己的產出&quot;). The T2 異模型互審鏈 (cost→quality→ceiling→frontier) is preserved in §3.3 機制 1-2. ✅</p><h3 id="d6-§5-2-claim-確定性-gate-永遠-main-親跑-—-fusion-不改變-gate-執行者-—-consistent-✅" tabindex="-1">D6. §5.2 claim: &quot;確定性 gate 永遠 main 親跑 — Fusion 不改變 gate 執行者&quot; — CONSISTENT ✅ <a class="header-anchor" href="#d6-§5-2-claim-確定性-gate-永遠-main-親跑-—-fusion-不改變-gate-執行者-—-consistent-✅" aria-label="Permalink to &quot;D6. §5.2 claim: &quot;確定性 gate 永遠 main 親跑 — Fusion 不改變 gate 執行者&quot; — CONSISTENT ✅&quot;">​</a></h3><p>delegation-protocol.md §1 T0: &quot;一次性的確定性檢查（單發 grep/test/healthcheck——這類 gate <strong>必須</strong>親跑,不經 subagent 中介）&quot;. The design preserves this (Task 1 single-file = T0 exception, main親做). ✅</p><h3 id="d7-agents-md-§4-prohibitions-—-no-violation-detected" tabindex="-1">D7. AGENTS.md §4 prohibitions — no violation detected <a class="header-anchor" href="#d7-agents-md-§4-prohibitions-—-no-violation-detected" aria-label="Permalink to &quot;D7. AGENTS.md §4 prohibitions — no violation detected&quot;">​</a></h3><p>Checked the 5 prohibitions: (1) no <code>git add -A</code> guidance in design — ✅; (2) the design does not instruct auto-fixing out-of-scope bugs — ✅ (it defers to delegation-protocol); (3) no prod changes proposed without confirmation — ✅; (4) the design does not skip <code>/deep-review</code> — ✅; (5) no emojis in the design files (verified by reading) — ✅. <strong>No §4 violations.</strong></p><hr><h2 id="part-e-risk-assessment-completeness" tabindex="-1">Part E: Risk Assessment Completeness <a class="header-anchor" href="#part-e-risk-assessment-completeness" aria-label="Permalink to &quot;Part E: Risk Assessment Completeness&quot;">​</a></h2><h3 id="e1-unaddressed-risk-1-verification-cost-death-spiral-for-high-volume-sidekick-tasks" tabindex="-1">E1. Unaddressed risk #1: Verification cost death-spiral for high-volume sidekick tasks <a class="header-anchor" href="#e1-unaddressed-risk-1-verification-cost-death-spiral-for-high-volume-sidekick-tasks" aria-label="Permalink to &quot;E1. Unaddressed risk #1: Verification cost death-spiral for high-volume sidekick tasks&quot;">​</a></h3><p>The design requires Main to mechanically re-verify sidekick output (§6). For Task 5 (16 PRs), if Main must re-read + re-grep each PR, the verification overhead scales with sidekick volume. At sufficient scale, <strong>the verifier (Main, ceiling-priced) becomes the bottleneck and cost driver</strong>, potentially inverting the savings. The design treats verification as a fixed-quality gate but does not model its scaling. This is a real architectural risk: the cheaper the sidekick, the more output it produces, the more Main must verify — a perverse incentive. <strong>Mitigation not in §6: stratified verification (sample-audit N% of PRs, full-verify only on anomaly) per delegation-protocol §6 (&quot;ceiling 產出 → 機械 gate + 關鍵判斷抽問&quot;) — but the design applies &quot;機械重驗&quot; uniformly without stratification.</strong></p><h3 id="e2-unaddressed-risk-2-prompt-cache-namespace-fragmentation-across-multi-model-sessions" tabindex="-1">E2. Unaddressed risk #2: Prompt-cache namespace fragmentation across multi-model sessions <a class="header-anchor" href="#e2-unaddressed-risk-2-prompt-cache-namespace-fragmentation-across-multi-model-sessions" aria-label="Permalink to &quot;E2. Unaddressed risk #2: Prompt-cache namespace fragmentation across multi-model sessions&quot;">​</a></h3><p>The design assumes cache is a single shared resource. In reality, each model has its own cache namespace. In the Factory path with Router (per-task routing) + compactionModel (Haiku) + sidekick (cost), a single session may touch 3-4 different models&#39; caches. The <em>aggregate</em> cache hit rate may be lower than a single-model session because each model&#39;s prefix is built independently. The design&#39;s &quot;zero cache penalty&quot; framing hides that <strong>multi-model sessions may have lower overall cache efficiency than mono-model sessions</strong>, even if each <em>switch</em> is free. This is not in §6.</p><h3 id="e3-unaddressed-risk-3-checkpoint-persistence-in-ephemeral-cloud-environments-partially-in-glm-validation-not-in-main-§6" tabindex="-1">E3. Unaddressed risk #3: Checkpoint persistence in ephemeral/cloud environments (partially in GLM validation, not in main §6) <a class="header-anchor" href="#e3-unaddressed-risk-3-checkpoint-persistence-in-ephemeral-cloud-environments-partially-in-glm-validation-not-in-main-§6" aria-label="Permalink to &quot;E3. Unaddressed risk #3: Checkpoint persistence in ephemeral/cloud environments (partially in GLM validation, not in main §6)&quot;">​</a></h3><p>GLM validation §優化項 4 non-blocking caveat 1 documents that <code>claude-progress.json</code> is gitignored + ephemeral in cloud containers (handoff GOTCHAS G4 real failure case), so the checkpoint-based sidekick persistence simulation <strong>fails in cloud/fresh-clone environments</strong>. This is a real, documented limitation — but it lives only in the GLM sub-report, <strong>not in the main design plan §6 risks</strong>. The main plan §6 risk 1 mentions &quot;Phase 2 persistent sidekick 需新功能&quot; but does <strong>not</strong> mention that even the Phase 1 checkpoint simulation is environment-fragile. <strong>Recommend: promote GLM&#39;s ephemeral caveat to main §6.</strong></p><h3 id="e4-eval-hack-risk-for-open-source-models-—-addressed-in-§3-3-but-inadequately-scoped" tabindex="-1">E4. &quot;Eval-hack risk for open-source models&quot; — addressed in §3.3 but inadequately scoped <a class="header-anchor" href="#e4-eval-hack-risk-for-open-source-models-—-addressed-in-§3-3-but-inadequately-scoped" aria-label="Permalink to &quot;E4. &quot;Eval-hack risk for open-source models&quot; — addressed in §3.3 but inadequately scoped&quot;">​</a></h3><p>§3.3 機制 3 says &quot;檔位越高驗證越嚴（frontier = +對抗稽核）&quot; and §6 risk 4 says &quot;開源模型 eval-hack 風險未知&quot;. model-profiles.md §1 rates non-Claude models as &quot;未知=當最高處理&quot; (treat unknown as highest risk) and §6 (non-Claude接入程序) says first calibration requires 5-10 representative tasks <em>including eval-hack trap tasks</em> in the actual non-Claude environment — status <strong>BLOCKED-EXTERNAL</strong> (cannot run in Claude Code session). <strong>The design&#39;s Phase 2 Factory BYOK path (sidekick = GLM-5.2 or Haiku) implicitly assumes open-source sidekick capability is adequate, but the workspace SSoT says open-source model calibration is BLOCKED and unverified.</strong> The design should explicitly gate the GLM/Kimi sidekick path on completing the §6 non-Claude calibration procedure, not assume it. Currently §4.1 assigns GLM-5.2 as &quot;ceiling 檔,開源&quot; with &quot;SWE-bench Pro 62.1% 接近 Opus&quot; — but model-profiles.md §0 notes GLM-5.2 is &quot;<strong>目前不在 workspace 使用</strong>;其 Z.ai API 走中國伺服器有 GDPR/合規風險,企業任務勿用 API 模式&quot;. <strong>The design uses GLM-5.2 as a reviewer/simulator without addressing the documented GDPR/compliance risk for enterprise tasks.</strong> This is a compliance gap, not just an eval-hack gap.</p><h3 id="e5-model-availability-deprecation-risk-—-not-addressed" tabindex="-1">E5. Model availability/deprecation risk — NOT addressed <a class="header-anchor" href="#e5-model-availability-deprecation-risk-—-not-addressed" aria-label="Permalink to &quot;E5. Model availability/deprecation risk — NOT addressed&quot;">​</a></h3><p>§6 lists 5 risks; none cover model deprecation. Yet model-profiles.md §0 documents a <strong>real precedent</strong>: &quot;Fable 曾 72h 無預警下架實證,含 Bedrock&quot;. The entire Fusion design assumes GLM-5.2, Kimi K2.7, Haiku 4.5, Opus 4.8, Fable 5 are stably available. If any sidekick model (especially open-source GLM/Kimi with no SLA) is deprecated or becomes unavailable, the architecture&#39;s cost model breaks. The design should add: &quot;<strong>Model-deprecation contingency</strong>: sidekick tier must have ≥2 qualified candidates; if a sidekick model is discontinued, fallback to next cost-tier Claude model (per model-profiles §0 single-vendor risk note).**&quot;</p><h3 id="e6-unaddressed-risk-4-router-black-box-verification-loop-cost" tabindex="-1">E6. Unaddressed risk #4: Router black-box + verification loop cost <a class="header-anchor" href="#e6-unaddressed-risk-4-router-black-box-verification-loop-cost" aria-label="Permalink to &quot;E6. Unaddressed risk #4: Router black-box + verification loop cost&quot;">​</a></h3><p>§6 risk 2 flags Router as black-box (43% vendor-reported). Good. But the <em>verification</em> of Router&#39;s decisions (per §5.1 &quot;供應商工具也需信任但驗證&quot;) has a cost the design does not model: if Main must audit Router&#39;s per-task routing choices, that is additional Main overhead. The design assumes Router is trusted-enough to not audit per-task, which <em>contradicts</em> §5.1&#39;s own principle. Either Router is trusted (drop the §5.1 caveat) or it is audited (add the audit cost). The design holds both positions simultaneously.</p><hr><h2 id="part-f-feasibility" tabindex="-1">Part F: Feasibility <a class="header-anchor" href="#part-f-feasibility" aria-label="Permalink to &quot;Part F: Feasibility&quot;">​</a></h2><h3 id="f1-phase-1-zero-code-changes-—-verified-as-accurate-with-the-checkpoint-caveat" tabindex="-1">F1. Phase 1 &quot;zero code changes&quot; — VERIFIED as accurate (with the checkpoint caveat) <a class="header-anchor" href="#f1-phase-1-zero-code-changes-—-verified-as-accurate-with-the-checkpoint-caveat" aria-label="Permalink to &quot;F1. Phase 1 &quot;zero code changes&quot; — VERIFIED as accurate (with the checkpoint caveat)&quot;">​</a></h3><p>GLM validation independently verified 3/4 Phase 1 optimizations are zero-modification (✅×3) and 1/4 (checkpoint persistence) needs a small prompt-layer or 1-line agent-rule tweak (⚠️). I re-verified the load-bearing claims:</p><ul><li>multi-mode-agent.md frontmatter confirms <code>model: sonnet</code> default + parent override at spawn. ✅</li><li>multi-mode-skill §1 confirms 0-1 位置 → cost → haiku → inline/spawn. ✅</li><li>delegation-protocol §4 confirms 回報合約 (conclusion + file:line). ✅</li><li>context-management.md Static First confirms cache prefix stability. ✅</li></ul><p><strong>The &quot;zero code changes&quot; claim for 3/4 items is accurate.</strong> The 1/4 (checkpoint) is honestly flagged by GLM as ⚠️, not oversold. <strong>Phase 1 is feasible as described.</strong> ✅</p><h3 id="f2-checkpoint-based-persistence-simulation-—-realistic-but-explicitly-a-simulation-not-persistent-cache" tabindex="-1">F2. Checkpoint-based persistence simulation — realistic but explicitly a simulation, not persistent cache <a class="header-anchor" href="#f2-checkpoint-based-persistence-simulation-—-realistic-but-explicitly-a-simulation-not-persistent-cache" aria-label="Permalink to &quot;F2. Checkpoint-based persistence simulation — realistic but explicitly a simulation, not persistent cache&quot;">​</a></h3><p>The design plan §2.3 itself states: &quot;這不是真正的 cache 持久化,但可減少重複 context 建構的 token 開銷.&quot; GLM validation independently confirms the checkpoint infrastructure (schema + hooks + skill) exists but flags (a) semantic misalignment (checkpoint is for main-task resume, not sidekick cumulative context), (b) ephemeral/cloud failure (GOTCHAS G4), (c) missing sidekick read entry point. <strong>The design is honest that this is a simulation. The feasibility concern is whether the <em>token savings</em> claimed in the simulation (which assumes &quot;Phase 2/Factory 已落地&quot; per token-sim §5 limitation 4) actually materialize in Phase 1 with one-shot spawns.</strong> They do not fully — Phase 1 sidekick is one-shot, so the &quot;sidekick 持久 context&quot; savings in Tasks 3/5 are Phase 2/Factory savings, not Phase 1. The simulation acknowledges this (limitation 4) but the main plan&#39;s Phase 1 framing does not clearly separate &quot;Phase 1 feasible&quot; from &quot;Phase 1 savings&quot;. <strong>Recommend: state that Phase 1 delivers the architecture, not the headline savings; savings require Phase 2/Factory.</strong></p><h3 id="f3-factory-phase-2-—-feasible-with-the-undocumented-field-caveats-from-b2" tabindex="-1">F3. Factory Phase 2 — feasible with the undocumented-field caveats from B2 <a class="header-anchor" href="#f3-factory-phase-2-—-feasible-with-the-undocumented-field-caveats-from-b2" aria-label="Permalink to &quot;F3. Factory Phase 2 — feasible with the undocumented-field caveats from B2&quot;">​</a></h3><p>GLM-B produced a concrete step-by-step guide with 8 doc URLs (32 <code>docs.factory.ai</code> mentions, ≥3 ✅). The configuration is feasible <em>if</em> the three undocumented assumptions in B3 hold (compactionModel mid-session safety, compaction-trigger signal mechanism, Router+compactionModel interaction). <strong>Feasible contingent on empirical verification of B3 assumptions.</strong> Not a hand-wave, but not yet verified.</p><h3 id="f4-factory-phase-3-api-mid-session-fusion-—-feasible-in-api-mechanics-unproven-in-trigger-mechanism" tabindex="-1">F4. Factory Phase 3 (API mid-session Fusion) — feasible in API mechanics, unproven in trigger mechanism <a class="header-anchor" href="#f4-factory-phase-3-api-mid-session-fusion-—-feasible-in-api-mechanics-unproven-in-trigger-mechanism" aria-label="Permalink to &quot;F4. Factory Phase 3 (API mid-session Fusion) — feasible in API mechanics, unproven in trigger mechanism&quot;">​</a></h3><p>The PATCH mechanics are documented. The &quot;detect compaction triggered → PATCH&quot; loop (§2.4 Phase 3) is the unproven part (B3 assumption 2). Without a documented webhook/event/polling contract for compaction-trigger, Phase 3 is <strong>design-complete but integration-unproven</strong>. This is acceptable for a &quot;proposed&quot; architecture but should not be presented as &quot;現有能力&quot; — Phase 3 requires <em>building</em> the trigger-detection integration, which is code, not configuration.</p><hr><h2 id="mechanical-verification-results" tabindex="-1">Mechanical Verification Results <a class="header-anchor" href="#mechanical-verification-results" aria-label="Permalink to &quot;Mechanical Verification Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Expected</th><th>Actual</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td><code>wc -c</code> protocol draft ≤ 1200 bytes</td><td>≤1200</td><td>1077</td><td>✅ Pass</td></tr><tr><td>2</td><td><code>grep -ciE &#39;opus|sonnet|haiku|fable|glm|kimi|gpt|claude|anthropic|openai&#39;</code> protocol draft = 0</td><td>0</td><td>0</td><td>✅ Pass</td></tr><tr><td>3</td><td><code>grep -c &#39;docs.factory.ai&#39;</code> phase2-config ≥ 3</td><td>≥3</td><td>32</td><td>✅ Pass</td></tr><tr><td>4</td><td>Token sim Task 3 math (existing $0.4613, fusion $0.2925, 37%)</td><td>match</td><td>$0.4612 / $0.2925 / 36.6%</td><td>✅ Pass (rounding)</td></tr><tr><td>5</td><td>Token sim Task 5 math (existing $1.536, fusion $0.729, 53%)</td><td>match</td><td>$1.536 / $0.729 / 52.5%</td><td>✅ Pass (rounding)</td></tr><tr><td>6</td><td>Token sim aggregate (-35.2%)</td><td>match</td><td>-35.2%</td><td>✅ Pass</td></tr><tr><td>7</td><td>context-management.md mid-session prohibition exists</td><td>present</td><td>present (verbatim)</td><td>✅ Pass</td></tr><tr><td>8</td><td>multi-mode-skill §0 &quot;mid-session 不切 model&quot; invariant</td><td>present</td><td>present (verbatim)</td><td>✅ Pass</td></tr><tr><td>9</td><td>delegation-protocol §6 &quot;驗證不自驗&quot; exists</td><td>present</td><td>present (verbatim)</td><td>✅ Pass</td></tr><tr><td>10</td><td>HARNESS-CORE-v3 L1 zero-model-name rule</td><td>present</td><td>present (&quot;L1 不出現模型名&quot;)</td><td>✅ Pass</td></tr><tr><td>11</td><td>Live AGENTS.md has §7 Fusion Protocol merged</td><td>absent (proposal)</td><td>absent (no §7 in live file)</td><td>⚠️ N/A — draft not merged</td></tr><tr><td>12</td><td>model-profiles §0 GLM-5.2 GDPR/compliance caveat</td><td>present</td><td>present (&quot;Z.ai API 走中國伺服器有 GDPR/合規風險,企業任務勿用&quot;)</td><td>✅ Pass (caveat exists; design did not cite it)</td></tr></tbody></table><hr><h2 id="critical-issues-must-fix-before-implementation" tabindex="-1">Critical Issues (must fix before implementation) <a class="header-anchor" href="#critical-issues-must-fix-before-implementation" aria-label="Permalink to &quot;Critical Issues (must fix before implementation)&quot;">​</a></h2><ol><li><p><strong>Cache-zero claim is over-stated and conflates compactionModel swap with main-model swap (A4).</strong> The &quot;零額外 cache 懲罰&quot; claim rigorously holds <em>only</em> for the compactionModel field. Swapping the main session model at compaction time still costs a one-time prefix re-cache on the new model. §2.2 L3 and §2.5 Protocol must state this precisely and scope the cache-zero benefit to the compactionModel lever only. This is load-bearing because the entire &quot;compaction-time switching = free&quot; narrative drives the Factory Phase 3 design.</p></li><li><p><strong>Internal contradiction on <code>providerLock</code> (B2).</strong> Main plan §1.3 lists <code>providerLock</code> as &quot;✅ Session 層級&quot; (supported feature); GLM-B sub-report finds it is <em>not</em> a settable CLI switch and <code>providerLockTimestamp</code> semantics are undocumented. The main plan must be corrected to match GLM-B&#39;s verified finding, or implementers will attempt to set a non-existent switch.</p></li><li><p><strong>Factory Phase 3 trigger-detection mechanism is unspecified (B3 assumption 2).</strong> &quot;偵測 compaction 觸發 → PATCH model&quot; assumes an event/polling contract that no Factory document describes. Phase 3 must either (a) specify the actual detection mechanism (webhook? polling GET? CLI hook?) with doc citation, or (b) be downgraded from &quot;現有能力,配置層&quot; to &quot;需整合開發&quot;. As written, Phase 3 is integration-unproven.</p></li><li><p><strong>Headline -35.2% savings is single-task-dominated and task-structure-fragile (C1).</strong> 84% of the headline comes from Task 5 (large migration, 56% cost share), which is itself based on an unconfirmed Twitter-sourced figure. The design must lead with <em>both</em> frequency-weighted (+2.8%) and cost-weighted (-35.2%) views and state explicitly that savings are realized only on mechanical-proportion-heavy tasks. Leading with -35.2% alone is misleading for a ceiling-tier doc.</p></li><li><p><strong>GLM-5.2 / Kimi K2.7 used as reviewers/simulators without addressing documented GDPR/compliance risk (E4).</strong> model-profiles.md §0 explicitly warns &quot;Z.ai API 走中國伺服器有 GDPR/合規風險,企業任務勿用 API 模式&quot; for GLM-5.2, and §6 marks non-Claude calibration as BLOCKED-EXTERNAL. The design assigns GLM-5.2 as ceiling-tier reviewer and Kimi as simulator without gating on the §6 calibration procedure or citing the compliance caveat. For an owner whose domains include ISO 27017 and enterprise GCP, this is a compliance gap that must be resolved before any BYOK sidekick deployment.</p></li></ol><hr><h2 id="minor-issues-should-fix" tabindex="-1">Minor Issues (should fix) <a class="header-anchor" href="#minor-issues-should-fix" aria-label="Permalink to &quot;Minor Issues (should fix)&quot;">​</a></h2><ol><li><p><strong>Layer numbering inconsistency (A1):</strong> §2.2 title says &quot;三層&quot; but diagram shows 4 boxes L0-L3. Rename to &quot;3 layers + 1 cross-cutting gate&quot; or renumber.</p></li><li><p><strong>Compaction Gate binding context unclear in diagram (A2):</strong> Annotate which context (Main vs Sidekick) the gate watches per harness; on Claude Code it watches Main only.</p></li><li><p><strong>Downgrade feedback loop scoped to Factory-only (A3):</strong> §2.5 Protocol downgrade row should note &quot;Factory path only; Claude Code = post-task escalation&quot; since Claude Code&#39;s router is static-position-count.</p></li><li><p><strong>Verification overhead not costed in token sim (C2):</strong> Main&#39;s mechanical re-verification of sidekick output (§6 requirement) is not in any Fusion column. Add ~10-20k Main input tokens for Task 5.</p></li><li><p><strong>&quot;Token 節省策略&quot; framing hides quality-investment cost increases (C3):</strong> Tasks 2 &amp; 4 cost <em>more</em> under Fusion by design (quality upgrade). Reframe §3 as &quot;Token 重分配 + 節省策略&quot; and explicitly mark Tasks 2 &amp; 4 as accepted quality-investment zones.</p></li><li><p><strong>§5.2 L1 row implies Protocol is enforced; it is a draft (D3):</strong> Add &quot;（草案,待 merge）&quot; to the §5.2 L1 zero-model-name row.</p></li><li><p><strong>Checkpoint ephemeral failure not in main §6 (E3):</strong> Promote GLM validation&#39;s cloud/ephemeral caveat (GOTCHAS G4) to main design plan §6 risks.</p></li><li><p><strong>Model-deprecation contingency missing (E5):</strong> Add a §6 risk for sidekick model deprecation (Fable 72h precedent documented in model-profiles §0); require ≥2 qualified sidekick candidates per tier.</p></li><li><p><strong>Router black-box + verification contradiction (E6):</strong> §5.1 says &quot;供應商工具也需信任但驗證&quot; but the design does not model Router-decision audit cost. Either trust Router (drop caveat) or add audit cost.</p></li><li><p><strong>Phase 1 framing conflates &quot;feasible&quot; with &quot;delivers savings&quot; (F2):</strong> Phase 1 delivers the architecture; headline savings require Phase 2/Factory (token-sim §5 limitation 4). State this separation explicitly.</p></li><li><p><strong>Protocol draft uses &quot;§7&quot; label but live AGENTS.md ends at §6b:</strong> When merging, verify §7 is the correct next section number and does not collide with future §6c/§7 additions.</p></li></ol><hr><h2 id="strengths-what-the-design-gets-right" tabindex="-1">Strengths (what the design gets right) <a class="header-anchor" href="#strengths-what-the-design-gets-right" aria-label="Permalink to &quot;Strengths (what the design gets right)&quot;">​</a></h2><ol><li><p><strong>Honest sub-report discipline.</strong> GLM-B explicitly flags 3 undocumented/unsupported Factory fields (providerLock, model ID strings, providerLockTimestamp semantics) rather than papering over them — exactly the &quot;trust but verify&quot; behavior the workspace demands. This is ceiling-tier integrity.</p></li><li><p><strong>Phase 1 &quot;zero code changes&quot; claim is verified accurate for 3/4 items.</strong> GLM validation independently confirmed each optimization against file:line evidence, and the ⚠️ on item 4 is honestly flagged, not oversold.</p></li><li><p><strong>Protocol draft is mechanically L1-compliant.</strong> 1077 bytes, 0 model names, uses tier words only — passes the HARNESS-CORE-v3 v3 鐵律. The draft is a clean, mergeable artifact.</p></li><li><p><strong>Token simulation arithmetic is correct.</strong> All spot-checked figures (Tasks 3, 5, aggregate) recompute to the reported values (rounding-only differences). No fabricated numbers.</p></li><li><p><strong>Claude Code vs Factory path divergence is correctly identified and routed around.</strong> The Claude Code mid-session prohibition (context-management.md) is accurately cited, and the sub-agent spawn workaround is genuinely compliant, not a workaround-in-name-only.</p></li><li><p><strong>§5.2 workspace-alignment table is largely accurate.</strong> 5 of 5 checked rules (mid-session, 指揮官不下場, 驗證不自驗, L1 零模型名, 確定性 gate) are correctly mapped to existing workspace rules with correct compliance behavior. No §4 prohibitions violated.</p></li><li><p><strong>Three-phase progressive rollout is sound.</strong> Each phase is independently verifiable, Phase 1 requires no code, and the design does not attempt a big-bang rebuild. This matches the workspace&#39;s &quot;漸進落地&quot; preference.</p></li><li><p><strong>Sidekick/sub-agent report contract (§4) is correctly inherited from delegation-protocol §4</strong> — conclusion + file:line, no raw dump. This preserves parent context hygiene.</p></li><li><p><strong>Compaction model = cost tier is a genuinely high-leverage, low-risk optimization</strong> (compaction is summarization, not reasoning; downgrading it has no quality loss). This is the design&#39;s strongest concrete saving lever and is correctly identified.</p></li><li><p><strong>Quality safeguards (§3.3) are correctly inherited</strong> — verification-not-self-verify, adversarial review, eval-hack defense, cross-model cross-check. The design does not sacrifice quality gates for savings.</p></li></ol><hr><h2 id="final-verdict" tabindex="-1">Final Verdict <a class="header-anchor" href="#final-verdict" aria-label="Permalink to &quot;Final Verdict&quot;">​</a></h2><p><strong>SHIP-WITH-CAVEATS</strong></p><p><strong>Rationale:</strong> The architecture is structurally sound, the Phase 1 feasibility claim is verified accurate (3/4 zero-modification, 1/4 honestly flagged), the protocol draft is mechanically L1-compliant, and the token arithmetic is correct. However, five critical issues must be resolved before implementation: the cache-zero claim is over-stated and conflates compactionModel swap with main-model swap; the main plan contradicts its own sub-report on <code>providerLock</code>; Factory Phase 3&#39;s compaction-trigger detection mechanism is unspecified and unproven; the headline -35.2% savings is single-task-dominated and task-structure-fragile (84% from one unconfirmed-source task); and GLM-5.2/Kimi are used without addressing the documented GDPR/compliance risk and BLOCKED-EXTERNAL calibration status. None of these are fatal — all are fixable with precise rewording, doc verification, and a compliance gate — but shipping as-is would propagate an over-claimed cache benefit, an internal contradiction, an unproven integration step, a misleading savings headline, and a compliance gap. Fix the 5 critical issues, then ship.</p>',99)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
